$:gh codespace ssh -c shiny-robot-v64x5jj4v4q2x96 -- bash -s <<'REMOTE_FILESYSTEM'
set -e
cd /workspaces/Terminals
git fetch origin main --quiet
git merge --ff-only origin/main
python3 - <<'PY'
from pathlib import Path
p=Path('workspaces/codespace-terminal-mcp/response-template.mjs')
s=p.read_text()
old='''    resources.push({
      uri: resource.uri,
      name: block.name,
      mimeType: resource.mimeType,
      content: resource.mimeType === 'application/json' ? JSON.parse(resource.text) : resource.text
    });'''
new='''    resources.push({
      type: 'text',
      content: resource.mimeType === 'application/json' ? JSON.parse(resource.text) : resource.text
    });'''
assert s.count(old)==1, 'Expected exact resources.push() block missing or duplicated'
p.write_text(s.replace(old,new))
p=Path('workspaces/codespace-terminal-mcp/response-template.test.mjs')
s=p.read_text()
old='''  const expected = new Map([
    ['resource://terminals/references/imperatives', 'imperatives.json'],
    [uri, 'account-custom-instructions.json']
  ]);
  for (const resource of result.resources) {
    const filename = expected.get(resource.uri);
    assert.ok(filename, 'unexpected resource URI');
    assert.equal(resource.mimeType, 'application/json');
    const source = JSON.parse(await readFile(new URL('../../references/' + filename, import.meta.url), 'utf8'));
    assert.deepEqual(resource.content, source);
  }'''
new='''  const filenames = ['imperatives.json', 'account-custom-instructions.json'];
  for (const [index, resource] of result.resources.entries()) {
    const source = JSON.parse(await readFile(new URL('../../references/' + filenames[index], import.meta.url), 'utf8'));
    assert.deepEqual(resource, { type: 'text', content: source });
  }'''
assert s.count(old)==1, 'Expected exact test assertion block missing or duplicated'
p.write_text(s.replace(old,new))
PY
